// simple_points.go — the ideal of a rational point ψ of the ring l[s][y] generated
// over a subfield l by two elements s and y. The point kills each x − ψ(x), and the
// elements congruent to their values modulo an ideal form a subring; its kernel is
// generated by s − ψ(s) and y − ψ(y); a simple root of an equation for y over l[s]
// relates the two generators by an element off the point; and such a relation makes
// the kernel an invertible fractional ideal.

package rational_point_ideal

import (
	"github.com/euc-ai/xugo/ext/on"
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/algebraic_element"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field"
	"github.com/euc-ai/xugo/library/proofs/algebra/group/comm_monoid"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/comm_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/invertible_fractional_ideal"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/polynomial/polynomial"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/polynomial/polynomial_division"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/polynomial/polynomial_evaluation"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/polynomial/polynomial_roots"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/quotient_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_homomorphism"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_ideal"
	"github.com/euc-ai/xugo/library/proofs/sets/set_order"
	"github.com/euc-ai/xugo/library/proofs/vector/vec_space"
	"github.com/euc-ai/xugo/library/registry"
)

// PointResidueSubring — the elements of a ring T congruent modulo an ideal I to
// their value under a ring map ψ from T onto a subfield l fixing l form a subring
// holding l: the congruences add, negate and multiply, since ψ does.
var PointResidueSubring = pointResidueSubringThm{family.Add(registry.ProofEntry{
	Name: "PointResidueSubring",
	Key:  "prop_bcd7b377188c596b",
	Build: family.Theorem(Statement{
		Abbrev: Abbrev{
			{Name: "congruent", Text: "{x:A | x ∈ T ∧ x - ψ(x) ∈ I}"},
		},
		Binders: "∀M:field_on(A). ∀l T I:set(A). ∀ψ:(A → A).",
		Hypotheses: []string{
			"subfield(M, l)",
			"subring(field_ring(M), T)",
			"l ⊆ T",
			"ring_ideal(restrict_ring(field_ring(M), T), I)",
			"ring_homomorphism(restrict_ring(field_ring(M), T), restrict_ring(field_ring(M), l), ψ)",
			"∀c:A. c ∈ l ⇒ ψ(c) = c",
		},
		Conclusion: "subring(field_ring(M), «congruent») ∧ l ⊆ «congruent»",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			l, T, I *Expr[Set[A]],
			ψ *Arrow[A, A],
			lSubfield, subringT, lInT, ideal, hom, fixes Fact,
		) {
			m := a.TermAs[FieldOps[A]]("M")
			fieldRing := a.TermAs[RingOps[A]]("field_ring(M)")
			opsT := a.TermAs[RingOps[A]]("restrict_ring(field_ring(M), T)")
			congruent := a.TermAs[Set[A]]("«congruent»")
			TInField := a.Have(
				"T lies in the field",
				"T ⊆ M.carrier",
				By(subringT, comm_ring.SubringSubset.At(fieldRing, T)))
			lInField := a.Have(
				"l lies in the field",
				"l ⊆ M.carrier",
				By(lSubfield, field.SubfieldSubset.At(m, l)))
			values := a.Have(
				"ψ takes T into l",
				"∀x:A. x ∈ T ⇒ ψ(x) ∈ l",
				By(ring_homomorphism.MapIn.Read(hom)))
			sums := a.Have(
				"a sum of congruent elements is congruent",
				"∀x y:A. x ∈ «congruent» ∧ y ∈ «congruent» ⇒ x + y ∈ «congruent»",
				Derive(func(b *Argument) {
					x := b.FixAs[A]("x")
					y := b.FixAs[A]("y")
					members := b.Assume()
					parts := b.Have(
						"x and y lie in T, each congruent to its value",
						"x ∈ T ∧ y ∈ T ∧ x - ψ(x) ∈ I ∧ y - ψ(y) ∈ I",
						By(members))
					inField := b.Have(
						"x, y and their values lie in the field",
						"x ∈ M.carrier ∧ y ∈ M.carrier ∧ ψ(x) ∈ M.carrier ∧ ψ(y) ∈ M.carrier",
						BySets(parts, TInField, lInField, values.At(x), values.At(y)))
					additive := b.Have(
						"ψ is additive",
						"ψ(x + y) = ψ(x) + ψ(y)",
						By(parts, ring_homomorphism.MapAdd.Read(hom).AsFact().At(x, y)))
					regroup := b.Have(
						"the difference splits into the two differences",
						"(x + y) - (ψ(x) + ψ(y)) = (x - ψ(x)) + (y - ψ(y))",
						ByArith(M, inField))
					b.Show(
						"an ideal holds the sum of two of its members",
						By(
							parts,
							additive,
							regroup,
							subringT,
							comm_ring.SubringAdd.At(fieldRing, T, x, y),
							ideal,
							ring_ideal.IdealAdd.At(opsT, I, b.TermAs[A]("x - ψ(x)"), b.TermAs[A]("y - ψ(y)"))))
				}))
			products := a.Have(
				"a product of congruent elements is congruent",
				"∀x y:A. x ∈ «congruent» ∧ y ∈ «congruent» ⇒ x * y ∈ «congruent»",
				Derive(func(b *Argument) {
					x := b.FixAs[A]("x")
					y := b.FixAs[A]("y")
					members := b.Assume()
					parts := b.Have(
						"x and y lie in T, each congruent to its value",
						"x ∈ T ∧ y ∈ T ∧ x - ψ(x) ∈ I ∧ y - ψ(y) ∈ I",
						By(members))
					valueInT := b.Have(
						"the value of y lies in l, so in T",
						"ψ(y) ∈ l ∧ ψ(y) ∈ T",
						BySets(parts, lInT, values.At(y)))
					inField := b.Have(
						"x, y and their values lie in the field",
						"x ∈ M.carrier ∧ y ∈ M.carrier ∧ ψ(x) ∈ M.carrier ∧ ψ(y) ∈ M.carrier",
						BySets(parts, TInField, lInField, values.At(x), values.At(y)))
					multiplicative := b.Have(
						"ψ is multiplicative",
						"ψ(x * y) = ψ(x) * ψ(y)",
						By(parts, ring_homomorphism.MapMul.Read(hom).AsFact().At(x, y)))
					regroup := b.Have(
						"the difference is x times the difference for y plus ψ(y) times the one for x",
						"x * y - ψ(x) * ψ(y) = x * (y - ψ(y)) + ψ(y) * (x - ψ(x))",
						ByArith(M, inField))
					b.Show(
						"an ideal of T absorbs multiples and holds sums",
						By(
							parts,
							valueInT,
							multiplicative,
							regroup,
							subringT,
							comm_ring.SubringMul.At(fieldRing, T, x, y),
							ideal,
							ring_ideal.IdealMul.At(opsT, I, x, b.TermAs[A]("y - ψ(y)")),
							ring_ideal.IdealMul.At(opsT, I, b.TermAs[A]("ψ(y)"), b.TermAs[A]("x - ψ(x)")),
							ring_ideal.IdealAdd.At(opsT, I, b.TermAs[A]("x * (y - ψ(y))"), b.TermAs[A]("ψ(y) * (x - ψ(x))"))))
				}))
			negatives := a.Have(
				"the negative of a congruent element is congruent",
				"∀x:A. x ∈ «congruent» ⇒ -x ∈ «congruent»",
				Derive(func(b *Argument) {
					x := b.FixAs[A]("x")
					member := b.Assume()
					parts := b.Have(
						"x lies in T, congruent to its value",
						"x ∈ T ∧ x - ψ(x) ∈ I",
						By(member))
					inField := b.Have(
						"x and its value lie in the field",
						"x ∈ M.carrier ∧ ψ(x) ∈ M.carrier",
						BySets(parts, TInField, lInField, values.At(x)))
					minusOne := b.Have(
						"minus one lies in T",
						"-M.one ∈ T",
						By(subringT, comm_ring.SubringDef.At(fieldRing, T)))
					negated := b.Have(
						"ψ keeps negatives",
						"ψ(-x) = -ψ(x)",
						By(parts, ring_homomorphism.MapNeg.Read(hom).AsFact().At(x)))
					regroup := b.Have(
						"the difference is minus one times the difference for x",
						"-x - -ψ(x) = -M.one * (x - ψ(x))",
						ByArith(M, inField))
					b.Show(
						"an ideal of T absorbs multiples",
						By(
							parts,
							minusOne,
							negated,
							regroup,
							subringT,
							comm_ring.SubringDef.At(fieldRing, T),
							ideal,
							ring_ideal.IdealMul.At(opsT, I, b.TermAs[A]("-M.one"), b.TermAs[A]("x - ψ(x)"))))
				}))
			constants := a.Have(
				"a member of l is its own value",
				"∀c:A. c ∈ l ⇒ c ∈ «congruent»",
				Derive(func(b *Argument) {
					c := b.FixAs[A]("c")
					inL := b.Assume()
					inField := b.Have(
						"c lies in T and in the field",
						"c ∈ T ∧ c ∈ M.carrier",
						BySets(inL, lInT, lInField))
					zeroDifference := b.Have(
						"c less itself is zero",
						"c - c = M.zero",
						ByArith(M, inField))
					b.Show(
						"zero lies in the ideal",
						By(Normalized, inL, inField, fixes.At(c), zeroDifference, ideal, ring_ideal.IdealZero.At(opsT, I)))
				}))
			inField := a.Have(
				"the congruent elements lie in the field",
				"«congruent» ⊆ M.carrier",
				BySets(TInField))
			zeroIn := a.Have(
				"zero is congruent",
				"M.zero ∈ «congruent»",
				By(lSubfield, field.SubfieldZero.At(m, l), constants))
			oneIn := a.Have(
				"one is congruent",
				"M.one ∈ «congruent»",
				By(lSubfield, field.SubfieldOne.At(m, l), constants))
			subringCongruent := a.Have(
				"so the congruent elements form a subring",
				"subring(field_ring(M), «congruent»)",
				By(
					inField,
					zeroIn,
					oneIn,
					sums,
					negatives,
					products,
					comm_ring.SubringDef.At(fieldRing, congruent)))
			a.Show(
				"a subring holding l",
				BySets(subringCongruent, constants))
		}),
})}

// PointKillsDifference — a ring map ψ from a subring T of a field to a part l of T
// that it fixes kills x − ψ(x) for every x in T: ψ(x) lies in l, so ψ(ψ(x)) = ψ(x).
var PointKillsDifference = pointKillsDifferenceThm{family.Add(registry.ProofEntry{
	Name: "PointKillsDifference",
	Key:  "prop_7575355af87fd071",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀l T:set(A). ∀ψ:(A → A). ∀x:A.",
		Hypotheses: []string{
			"subring(field_ring(M), T)",
			"l ⊆ T",
			"ring_homomorphism(restrict_ring(field_ring(M), T), restrict_ring(field_ring(M), l), ψ)",
			"∀c:A. c ∈ l ⇒ ψ(c) = c",
			"x ∈ T",
		},
		Conclusion: "ψ(x - ψ(x)) = M.zero",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			l, T *Expr[Set[A]],
			ψ *Arrow[A, A],
			x *Expr[A],
			subringT, lInT, hom, fixes, xIn Fact,
		) {
			value := a.TermAs[A]("ψ(x)")
			valueIn := a.Have(
				"ψ(x) lies in l, so in T and in the field",
				"ψ(x) ∈ l ∧ ψ(x) ∈ T ∧ ψ(x) ∈ M.carrier",
				BySets(
					xIn,
					lInT,
					subringT,
					comm_ring.SubringSubset.At(a.TermAs[RingOps[A]]("field_ring(M)"), T),
					ring_homomorphism.MapIn.Read(hom).AsFact().At(x)))
			cancel := a.Have(
				"ψ(x) less itself is zero",
				"ψ(x) - ψ(x) = M.zero",
				ByArith(M, valueIn))
			a.Show(
				"ψ(x − ψ(x)) is ψ(x) less ψ(ψ(x)), which is ψ(x)",
				By(
					Normalized,
					xIn,
					valueIn,
					cancel,
					fixes.At(value),
					ring_homomorphism.MapSub.Read(hom).AsFact().At(x, value)))
		}),
})}

// MonogenicChartSubring — for s and y in a field M with a subfield l, l[s] is a
// subring of M holding l, and the chart l[s][y], monogenic over l[s], a subring of M,
// so a ring under its operations, holding l[s] and y, so l, s and y; a ring map ψ
// from the chart to l takes s and y into l.
var MonogenicChartSubring = monogenicChartSubringThm{family.Add(registry.ProofEntry{
	Name: "MonogenicChartSubring",
	Key:  "prop_9e53710d12df0698",
	Build: family.Theorem(Statement{
		Abbrev: Abbrev{
			{Name: "line", Text: "polynomial_image(field_ring(M), l, s)"},
			{Name: "chart", Text: "polynomial_image(field_ring(M), «line», y)"},
			{Name: "chartRing", Text: "restrict_ring(field_ring(M), «chart»)"},
		},
		Binders: "∀M:field_on(A). ∀l:set(A). ∀s y:A. ∀ψ:(A → A).",
		Hypotheses: []string{
			"subfield(M, l)",
			"s ∈ M.carrier",
			"y ∈ M.carrier",
			"ring_homomorphism(«chartRing», restrict_ring(field_ring(M), l), ψ)",
		},
		Conclusion: "subring(field_ring(M), «line») ∧ " +
			"l ⊆ «line» ∧ " +
			"subring(field_ring(M), «chart») ∧ " +
			"comm_ring_on(«chartRing») ∧ " +
			"«line» ⊆ «chart» ∧ " +
			"«chart» ⊆ M.carrier ∧ " +
			"l ⊆ «chart» ∧ " +
			"s ∈ «chart» ∧ " +
			"y ∈ «chart» ∧ " +
			"ψ(s) ∈ l ∧ " +
			"ψ(y) ∈ l",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			l *Expr[Set[A]],
			s, y *Expr[A],
			ψ *Arrow[A, A],
			lSubfield, sInField, yInField, hom Fact,
		) {
			fieldRing := a.TermAs[RingOps[A]]("field_ring(M)")
			line := a.TermAs[Set[A]]("«line»")
			chart := a.TermAs[Set[A]]("«chart»")
			sm := a.MemberOf[on.M](s, sInField)
			ym := a.MemberOf[on.M](y, yInField)
			lineData := a.Have(
				"l[s] is a subring holding l and s",
				"subring(field_ring(M), «line») ∧ l ⊆ «line» ∧ s ∈ «line»",
				By(lSubfield, algebraic_element.PolynomialImageRing.Read(M).At(l, sm)))
			chartData := a.Have(
				"l[s][y] is a subring holding l[s] and y",
				"subring(field_ring(M), «chart») ∧ «line» ⊆ «chart» ∧ y ∈ «chart»",
				By(lineData, algebraic_element.PolynomialImageSubring.Read(M).At(line, ym)))
			holds := a.Have(
				"so it holds l, s and y, and lies in the field",
				"l ⊆ «chart» ∧ s ∈ «chart» ∧ y ∈ «chart» ∧ «chart» ⊆ M.carrier",
				BySets(lineData, chartData, comm_ring.SubringSubset.At(fieldRing, chart)))
			a.Show(
				"it is a ring under the operations of M, and ψ takes s and y into l",
				By(
					lineData,
					chartData,
					holds,
					comm_ring.SubringRingOn.Read(field.RingOn.Read(M)).At(chart),
					ring_homomorphism.MapIn.Read(hom).AsFact().At(s),
					ring_homomorphism.MapIn.Read(hom).AsFact().At(y)))
		}),
})}

// MonogenicPointIdeal — a ring map ψ from l[s][y], monogenic over l[s], onto l
// fixing l has as kernel the ideal generated by s − ψ(s) and y − ψ(y), and every
// element x of l[s] differs from ψ(x) by a multiple of s − ψ(s). Modulo an ideal of
// the chart holding s − ψ(s), the elements congruent to their values form a ring
// holding l and s (PointResidueSubring), so all of l[s]; modulo both differences it
// holds y too, so the whole chart, and an element ψ kills is congruent to zero.
var MonogenicPointIdeal = monogenicPointIdealThm{family.Add(registry.ProofEntry{
	Name: "MonogenicPointIdeal",
	Key:  "prop_cbd5bfe3a67edc04",
	Build: family.Theorem(Statement{
		Abbrev: Abbrev{
			{Name: "line", Text: "polynomial_image(field_ring(M), l, s)"},
			{Name: "chart", Text: "polynomial_image(field_ring(M), «line», y)"},
			{Name: "chartRing", Text: "restrict_ring(field_ring(M), «chart»)"},
			{Name: "congruent", Text: "λI:set(A). {x:A | x ∈ «chart» ∧ x - ψ(x) ∈ I}"},
		},
		Binders: "∀M:field_on(A). ∀l:set(A). ∀s y:A. ∀ψ:(A → A).",
		Hypotheses: []string{
			"subfield(M, l)",
			"s ∈ M.carrier",
			"y ∈ M.carrier",
			"ring_homomorphism(«chartRing», restrict_ring(field_ring(M), l), ψ)",
			"∀c:A. c ∈ l ⇒ ψ(c) = c",
		},
		Conclusion: "{x:A | x ∈ «chart» ∧ ψ(x) = M.zero} = " +
			"ideal_span(«chartRing», {s - ψ(s), y - ψ(y)}) ∧ " +
			"(∀x:A. x ∈ «line» ⇒ ∃h:A. h ∈ «chart» ∧ x - ψ(x) = (s - ψ(s)) * h)",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			l *Expr[Set[A]],
			s, y *Expr[A],
			ψ *Arrow[A, A],
			lSubfield, sInField, yInField, hom, fixes Fact,
		) {
			m := a.TermAs[FieldOps[A]]("M")
			line := a.TermAs[Set[A]]("«line»")
			chart := a.TermAs[Set[A]]("«chart»")
			chartRing := a.TermAs[RingOps[A]]("«chartRing»")
			parts := a.Conjuncts(
				GroupPremises(M, lSubfield, sInField, yInField, hom, MonogenicChartSubring.At(m, l, s, y, ψ)),
				"l[s] is a subring of the field",
				"l[s] holds l",
				"the chart is a subring of the field",
				"the chart is a ring under the operations of M",
				"the chart holds l[s]",
				"the chart lies in the field",
				"the chart holds l",
				"the chart holds s",
				"the chart holds y",
				"ψ(s) lies in l",
				"ψ(y) lies in l")
			chartSubring, ring, chartInField := parts[2], parts[3], parts[5]
			lInChart, sIn, yIn := parts[6], parts[7], parts[8]
			valuesIn := a.Have(
				"the values of s and y lie in the chart and in the field",
				"ψ(s) ∈ «chart» ∧ ψ(y) ∈ «chart» ∧ ψ(s) ∈ M.carrier ∧ ψ(y) ∈ M.carrier",
				BySets(parts[9], parts[10], lInChart, chartInField))
			generators := a.Have(
				"s and y less their values lie in the chart",
				"s - ψ(s) ∈ «chart» ∧ y - ψ(y) ∈ «chart»",
				By(sIn, yIn, valuesIn, ring, comm_ring.SubIn.Read(ring)))
			vanish := a.Have(
				"ψ kills s and y less their values",
				"ψ(s - ψ(s)) = M.zero ∧ ψ(y - ψ(y)) = M.zero",
				By(
					M,
					chartSubring,
					lInChart,
					hom,
					fixes,
					sIn,
					yIn,
					PointKillsDifference.At(m, l, chart, ψ, s),
					PointKillsDifference.At(m, l, chart, ψ, y)))
			generatorSets := a.Have(
				"the generators lie in the chart",
				"{s - ψ(s)} ⊆ «chart» ∧ {s - ψ(s), y - ψ(y)} ⊆ «chart»",
				BySets(generators))
			principal := a.TermAs[Set[A]]("ideal_span(«chartRing», {s - ψ(s)})")
			span := a.TermAs[Set[A]]("ideal_span(«chartRing», {s - ψ(s), y - ψ(y)})")
			principalIdeal := a.Have(
				"the multiples of s − ψ(s) form an ideal of the chart",
				"ring_ideal(«chartRing», ideal_span(«chartRing», {s - ψ(s)}))",
				By(generatorSets, ring_ideal.SpanIdeal.Read(ring)))
			principalHolds := a.Have(
				"which holds s − ψ(s)",
				"s - ψ(s) ∈ ideal_span(«chartRing», {s - ψ(s)})",
				BySets(ring_ideal.SpanContains.At(chartRing, a.TermAs[Set[A]]("{s - ψ(s)}"))))
			spanIdeal := a.Have(
				"so do the combinations of s − ψ(s) and y − ψ(y)",
				"ring_ideal(«chartRing», ideal_span(«chartRing», {s - ψ(s), y - ψ(y)}))",
				By(generatorSets, ring_ideal.SpanIdeal.Read(ring)))
			spanHolds := a.Have(
				"which hold both differences",
				"s - ψ(s) ∈ ideal_span(«chartRing», {s - ψ(s), y - ψ(y)}) ∧ "+
					"y - ψ(y) ∈ ideal_span(«chartRing», {s - ψ(s), y - ψ(y)})",
				BySets(ring_ideal.SpanContains.At(chartRing, a.TermAs[Set[A]]("{s - ψ(s), y - ψ(y)}"))))
			modulo := a.Have(
				"modulo an ideal of the chart holding s − ψ(s), the "+
					"elements congruent to their values form a ring holding l[s]",
				Statement{
					Binders:    "∀I:set(A).",
					Hypotheses: []string{"ring_ideal(«chartRing», I)", "s - ψ(s) ∈ I"},
					Conclusion: "comm_ring_on(restrict_ring(field_ring(M), «congruent»(I))) ∧ «line» ⊆ «congruent»(I)",
				},
				Derive(func(b *Argument) {
					I := b.FixAs[Set[A]]("I")
					given := b.Conjuncts(
						b.Assume(),
						"I is an ideal of the chart",
						"it holds s − ψ(s)")
					congruent := b.TermAs[Set[A]]("«congruent»(I)")
					residues := b.Have(
						"the congruent elements form a subring holding l",
						"subring(field_ring(M), «congruent»(I)) ∧ l ⊆ «congruent»(I)",
						By(
							lSubfield,
							chartSubring,
							lInChart,
							given[0],
							hom,
							fixes,
							PointResidueSubring.Read(M).At(l, chart, I, ψ)))
					congruentRing := b.Have(
						"so they form a ring",
						"comm_ring_on(restrict_ring(field_ring(M), «congruent»(I)))",
						By(residues, comm_ring.SubringRingOn.Read(field.RingOn.Read(M)).At(congruent)))
					b.Show(
						"a ring holding l and s, it holds l[s]",
						By(
							residues,
							sIn,
							given[1],
							congruentRing,
							algebraic_element.PolynomialImageLeast.Read(M).At(l, congruent, s)))
				}))
			lineCongruent := a.Have(
				"so every element of l[s] is congruent to its value modulo s − ψ(s)",
				"«line» ⊆ «congruent»(ideal_span(«chartRing», {s - ψ(s)}))",
				By(principalIdeal, principalHolds, modulo.At(principal)))
			chartCongruent := a.Have(
				"modulo both differences the congruent elements hold l[s] and y, so the whole chart",
				"«chart» ⊆ «congruent»(ideal_span(«chartRing», {s - ψ(s), y - ψ(y)}))",
				By(
					spanIdeal,
					spanHolds,
					yIn,
					modulo.At(span),
					algebraic_element.PolynomialImageLeast.Read(M).At(
						line, a.TermAs[Set[A]]("«congruent»(ideal_span(«chartRing», {s - ψ(s), y - ψ(y)}))"), y)))
			kernel := a.TermAs[Set[A]]("{x:A | x ∈ «chart» ∧ ψ(x) = M.zero}")
			killsGenerators := a.Have(
				"ψ kills each of the two differences",
				"∀x:A. x ∈ {s - ψ(s), y - ψ(y)} ⇒ ψ(x) = M.zero",
				BySets(vanish))
			spanInKernel := a.Have(
				"so it kills their span",
				"ideal_span(«chartRing», {s - ψ(s), y - ψ(y)}) ⊆ {x:A | x ∈ «chart» ∧ ψ(x) = M.zero}",
				By(
					generatorSets,
					killsGenerators,
					ring_homomorphism.IdealSpanInKernel.Read(hom).At(a.TermAs[Set[A]]("{s - ψ(s), y - ψ(y)}")),
					ring_homomorphism.RingKernelDef.At(a.TermAs[A]("M.zero"), chart, ψ)))
			killedInSpan := a.Have(
				"an element ψ kills is congruent to zero",
				"∀x:A. x ∈ «chart» ∧ ψ(x) = M.zero ⇒ x ∈ ideal_span(«chartRing», {s - ψ(s), y - ψ(y)})",
				Derive(func(b *Argument) {
					b.FixAs[A]("x")
					given := b.Assume()
					congruent := b.Have(
						"x is congruent to its value",
						"x - ψ(x) ∈ ideal_span(«chartRing», {s - ψ(s), y - ψ(y)})",
						BySets(given, chartCongruent))
					inField := b.Have(
						"x lies in the field",
						"x ∈ M.carrier",
						BySets(given, chartInField))
					lessZero := b.Have(
						"x less zero is x",
						"x - M.zero = x",
						ByArith(M, inField))
					b.Show(
						"so x is in the span",
						By(given, congruent, lessZero))
				}))
			kernelInSpan := a.Have(
				"the kernel lies in the span",
				"{x:A | x ∈ «chart» ∧ ψ(x) = M.zero} ⊆ ideal_span(«chartRing», {s - ψ(s), y - ψ(y)})",
				BySets(killedInSpan))
			equal := a.Have(
				"the kernel is the span",
				"{x:A | x ∈ «chart» ∧ ψ(x) = M.zero} = ideal_span(«chartRing», {s - ψ(s), y - ψ(y)})",
				By(kernelInSpan, spanInKernel, set_order.SubsetAntisym.At(kernel, span)))
			multiples := a.Have(
				"the span of s − ψ(s) is its multiples",
				"ideal_span(«chartRing», {s - ψ(s)}) = {q:A | ∃r:A. r ∈ «chart» ∧ q = r * (s - ψ(s))}",
				By(generators, ring_ideal.PrincipalIdealMultiples.Read(ring)))
			principalClause := a.Have(
				"each element of l[s] less its value is a multiple of s − ψ(s)",
				"∀x:A. x ∈ «line» ⇒ ∃h:A. h ∈ «chart» ∧ x - ψ(x) = (s - ψ(s)) * h",
				Derive(func(b *Argument) {
					b.FixAs[A]("x")
					inLine := b.Assume()
					multiple := b.Have(
						"x less its value lies in the multiples of s − ψ(s)",
						"∃r:A. r ∈ «chart» ∧ x - ψ(x) = r * (s - ψ(s))",
						BySets(inLine, lineCongruent, multiples))
					r, rData := b.UnpackAs[A](multiple, "r")
					inField := b.Have(
						"r, s and ψ(s) lie in the field",
						"r ∈ M.carrier ∧ s ∈ M.carrier ∧ ψ(s) ∈ M.carrier",
						BySets(rData, chartInField, sInField, valuesIn))
					swap := b.Have(
						"the product commutes",
						"r * (s - ψ(s)) = (s - ψ(s)) * r",
						ByArith(M, inField))
					b.Take(r)
					b.Show(
						"r is the multiplier",
						By(rData, swap))
				}))
			a.Show(
				"the kernel, and each element of l[s] less its value as a multiple",
				By(equal, principalClause))
		}),
})}

// SimpleRootRelation — let y be a root of a polynomial G over l[s] and ψ a ring
// map from l[s][y] onto l fixing l. Dividing G less its value G(ψ(y)) by
// X − ψ(y) gives a quotient q with (y − ψ(y))·q(y) = −G(ψ(y)); the product rule
// makes G′(y) − q(y) a multiple of y − ψ(y), so ψ(q(y)) = ψ(G′(y)); and G(ψ(y)),
// an element of l[s] that ψ kills, is a multiple of s − ψ(s).
var SimpleRootRelation = simpleRootRelationThm{family.Add(registry.ProofEntry{
	Name: "SimpleRootRelation",
	Key:  "prop_179e0b8f450c8cd7",
	Build: family.Theorem(Statement{
		Abbrev: Abbrev{
			{Name: "line", Text: "polynomial_image(field_ring(M), l, s)"},
			{Name: "chart", Text: "polynomial_image(field_ring(M), «line», y)"},
			{Name: "chartRing", Text: "restrict_ring(field_ring(M), «chart»)"},
			{Name: "shifted", Text: "vec_sub(G, vec_scalar_mul(polynomial_eval(G, ψ(y)), basis_vector(0)))"},
			{Name: "linear", Text: "vec_sub(basis_vector(1), vec_scalar_mul(ψ(y), basis_vector(0)))"},
		},
		Binders: "∀M:field_on(A). ∀l:set(A). ∀s y:A. ∀G:(num → A). ∀ψ:(A → A).",
		Hypotheses: []string{
			"subfield(M, l)",
			"s ∈ M.carrier",
			"y ∈ M.carrier",
			"polynomial_over(«line», G)",
			"polynomial_eval(G, y) = M.zero",
			"ring_homomorphism(«chartRing», restrict_ring(field_ring(M), l), ψ)",
			"∀c:A. c ∈ l ⇒ ψ(c) = c",
		},
		Conclusion: "∃g h:A. " +
			"    g ∈ «chart» ∧ " +
			"    h ∈ «chart» ∧ " +
			"    ψ(g) = ψ(polynomial_eval(polynomial_derivative(G), y)) ∧ " +
			"    (y - ψ(y)) * g = (s - ψ(s)) * h",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			l *Expr[Set[A]],
			s, y *Expr[A],
			G *Arrow[Nat, A],
			ψ *Arrow[A, A],
			lSubfield, sInField, yInField, GOver, root, hom, fixes Fact,
		) {
			m := a.TermAs[FieldOps[A]]("M")
			fieldRing := a.TermAs[RingOps[A]]("field_ring(M)")
			zero := a.TermAs[A]("M.zero")
			line := a.TermAs[Set[A]]("«line»")
			chart := a.TermAs[Set[A]]("«chart»")
			sm := a.MemberOf[on.M](s, sInField)
			ym := a.MemberOf[on.M](y, yInField)
			parts := a.Conjuncts(
				GroupPremises(M, lSubfield, sInField, yInField, hom, MonogenicChartSubring.At(m, l, s, y, ψ)),
				"l[s] is a subring of the field",
				"l[s] holds l",
				"the chart is a subring of the field",
				"the chart is a ring under the operations of M",
				"the chart holds l[s]",
				"the chart lies in the field",
				"the chart holds l",
				"the chart holds s",
				"the chart holds y",
				"ψ(s) lies in l",
				"ψ(y) lies in l")
			lineSubring, lInLine, chartSubring, ring := parts[0], parts[1], parts[2], parts[3]
			lineInChart, chartInField, lInChart, yIn := parts[4], parts[5], parts[6], parts[8]
			lineRing := a.Have(
				"l[s] is a ring under the operations of M",
				"comm_ring_on(restrict_ring(field_ring(M), «line»))",
				By(lineSubring, comm_ring.SubringRingOn.Read(field.RingOn.Read(M)).At(line)))
			valuesIn := a.Have(
				"the values lie in l[s], in the chart and in the field",
				"ψ(y) ∈ «line» ∧ ψ(s) ∈ «chart» ∧ ψ(y) ∈ «chart» ∧ ψ(s) ∈ M.carrier ∧ ψ(y) ∈ M.carrier",
				BySets(parts[9], parts[10], lInLine, lInChart, chartInField))
			psiY := a.TermAs[A]("ψ(y)")
			pointIdeal := a.Conjuncts(
				GroupPremises(lSubfield, hom, fixes, MonogenicPointIdeal.Read(M).At(l, sm, ym, ψ)),
				"the kernel of ψ is generated by s − ψ(s) and y − ψ(y)",
				"an element of l[s] less its value is a multiple of s − ψ(s)")
			GOverChart := a.Have(
				"G is a polynomial over the chart",
				"polynomial_over(«chart», G)",
				By(GOver, lineInChart, polynomial.PolynomialOverMono.At(zero, line, chart, G)))
			value := a.TermAs[A]("polynomial_eval(G, ψ(y))")
			valueInLine := a.Have(
				"the value of G at ψ(y) lies in l[s]",
				"polynomial_eval(G, ψ(y)) ∈ «line»",
				By(GOver, valuesIn, polynomial_evaluation.EvalIn.Read(lineRing).AsFact().At(G, psiY)))
			valueIn := a.Have(
				"so in the chart and in the field",
				"polynomial_eval(G, ψ(y)) ∈ «chart» ∧ polynomial_eval(G, ψ(y)) ∈ M.carrier",
				BySets(valueInLine, lineInChart, chartInField))
			constant := a.TermAs[Fun[Nat, A]]("vec_scalar_mul(polynomial_eval(G, ψ(y)), basis_vector(0))")
			constantOver := a.Have(
				"the constant polynomial at that value is a polynomial over the chart",
				"polynomial_over(«chart», vec_scalar_mul(polynomial_eval(G, ψ(y)), basis_vector(0)))",
				By(
					valueIn,
					polynomial.PolynomialRingDef,
					ring_homomorphism.MapIn.Read(polynomial.ConstantPolynomialHomomorphism.Read(ring)).AsFact().At(
						value)))
			shifted := a.TermAs[Fun[Nat, A]]("«shifted»")
			shiftedOver := a.Have(
				"G less that constant is a polynomial over the chart",
				"polynomial_over(«chart», «shifted»)",
				By(GOverChart, constantOver, comm_ring.SubIn.Read(polynomial.PolynomialRingOn.Read(ring))))
			valueCancels := a.Have(
				"the value less itself is zero",
				"polynomial_eval(G, ψ(y)) - polynomial_eval(G, ψ(y)) = M.zero",
				ByArith(M, valueIn))
			shiftedRoot := a.Have(
				"which vanishes at ψ(y)",
				"polynomial_eval(«shifted», ψ(y)) = M.zero",
				By(
					GOverChart,
					constantOver,
					valuesIn,
					valueIn,
					valueCancels,
					polynomial_evaluation.EvalSub.Read(ring).AsFact().At(G, constant, psiY),
					polynomial_evaluation.EvalConstant.Read(ring).AsFact().At(value, psiY)))
			linear := a.TermAs[Fun[Nat, A]]("«linear»")
			factor := a.Unfolded(
				a.Have(
					"so X − ψ(y) divides it",
					"polynomial_divides(«chartRing», «linear», «shifted»)",
					By(
						shiftedOver,
						valuesIn,
						shiftedRoot,
						polynomial_roots.FactorTheorem.Read(ring).AsFact().At(shifted, psiY))),
				polynomial_division.PolynomialDividesDef)
			q, quotient := a.UnpackAs[Fun[Nat, A]](factor, "q")
			qParts := a.Conjuncts(
				quotient,
				"the quotient q is a polynomial over the chart",
				"G less its value at ψ(y) is (X − ψ(y)) q")
			qOver, qFactor := qParts[0], qParts[1]
			linearData := a.Conjuncts(
				GroupPremises(valuesIn, polynomial_roots.LinearFactor.Read(ring).AsFact().At(psiY)),
				"X − ψ(y) is a polynomial over the chart",
				"it is monic",
				"of degree at most one",
				"its value at a point is the point less ψ(y)",
				"it vanishes at ψ(y)",
				"of degree one in a nonzero ring")
			linearOver, linearValue := linearData[0], linearData[3]
			qDerivative := a.TermAs[Fun[Nat, A]]("polynomial_derivative(q)")
			qDerivativeOver := a.Have(
				"the derivative of q is a polynomial over the chart",
				"polynomial_over(«chart», polynomial_derivative(q))",
				By(qOver, polynomial.DerivativeOverCarrier.Read(ring).AsFact().At(q)))
			evaluations := a.Have(
				"the values of q and of its derivative at y lie in the chart",
				"polynomial_eval(q, y) ∈ «chart» ∧ polynomial_eval(polynomial_derivative(q), y) ∈ «chart»",
				By(qOver, qDerivativeOver, yIn, polynomial_evaluation.EvalIn.Read(ring)))
			evaluationsInField := a.Have(
				"so in the field",
				"polynomial_eval(q, y) ∈ M.carrier ∧ polynomial_eval(polynomial_derivative(q), y) ∈ M.carrier",
				BySets(evaluations, chartInField))
			atYDifference := a.Have(
				"at y the shifted polynomial takes minus the value, G vanishing there",
				"polynomial_eval(«shifted», y) = M.zero - polynomial_eval(G, ψ(y))",
				By(
					GOverChart,
					constantOver,
					yIn,
					valueIn,
					root,
					polynomial_evaluation.EvalSub.Read(ring).AsFact().At(G, constant, y),
					polynomial_evaluation.EvalConstant.Read(ring).AsFact().At(value, y)))
			atYProduct := a.Have(
				"and the product of y − ψ(y) and q(y)",
				"polynomial_eval(«shifted», y) = (y - ψ(y)) * polynomial_eval(q, y)",
				By(
					qFactor,
					linearOver,
					qOver,
					yIn,
					linearValue.At(y),
					polynomial_evaluation.EvalMul.Read(ring).AsFact().At(linear, q, y)))
			relation := a.Have(
				"so (y − ψ(y)) q(y) is minus the value of G at ψ(y)",
				"(y - ψ(y)) * polynomial_eval(q, y) = -polynomial_eval(G, ψ(y))",
				ByArith(M, atYDifference, atYProduct, valueIn, valuesIn, evaluationsInField, yInField))
			coefficients := a.Have(
				"the coefficients of G lie in the chart",
				"∀i:num. G(i) ∈ «chart»",
				By(GOverChart, polynomial.PolynomialOverDef))
			shiftedDerivative := a.Have(
				"G less a constant has the derivative of G",
				"polynomial_derivative(«shifted») = polynomial_derivative(G)",
				Derive(func(b *Argument) {
					b.Do(Funext())
					b.FixAs[Nat]("i")
					next := b.TermAs[Nat]("suc(i)")
					coefficient := b.Have(
						"the coefficient of G past i lies in the field",
						"G(suc(i)) ∈ M.carrier",
						BySets(coefficients.At(next), chartInField))
					b.Show(
						"the constant has no coefficient past the constant term",
						Simp(
							Fwd(polynomial.PolynomialDerivativeDef),
							Fwd(vec_space.VecSubDef),
							Fwd(vec_space.VecScalarMulDef),
							Fwd(vec_space.BasisVectorDef)),
						ByArith(M, coefficient, valueIn))
				}))
			linearDerivative := a.Have(
				"X − ψ(y) has derivative one",
				"polynomial_derivative(«linear») = basis_vector(0)",
				Derive(func(b *Argument) {
					b.Do(Funext())
					b.FixAs[Nat]("i")
					b.Do(Simp(
						Fwd(polynomial.PolynomialDerivativeDef),
						Fwd(vec_space.VecSubDef),
						Fwd(vec_space.VecScalarMulDef),
						Fwd(vec_space.BasisVectorDef)))
					b.Cases(b.Term("i = 0"))
					b.When(
						"at the constant term it is one",
						func(c *Argument, first Fact) {
							c.Do(first.Subst(), Simp(Fwd(comm_monoid.MonoidPowDef)))
							c.Show(
								"one times one",
								ByArith(M, valuesIn))
						})
					b.Otherwise(
						"past it zero",
						func(c *Argument, later Fact) {
							c.Show(
								"the coefficients of X − ψ(y) vanish past the first",
								ByArith(M, later, valuesIn))
						})
				}))
			coefficientsBoth := a.Have(
				"the coefficients of X − ψ(y) and of q lie in the chart",
				"∀i:num. "+
					"    vec_sub(basis_vector(1), vec_scalar_mul(ψ(y), basis_vector(0)), i) ∈ «chart» ∧ q(i) ∈ «chart»",
				By(linearOver, qOver, polynomial.PolynomialOverDef))
			qCoefficients := a.Have(
				"the coefficients of q lie in the chart",
				"∀i:num. q(i) ∈ «chart»",
				By(qOver, polynomial.PolynomialOverDef))
			productRule := a.Have(
				"by the product rule the derivative of G is q plus (X − ψ(y)) times the derivative of q",
				"polynomial_derivative(G) = vec_add(q, polynomial_mul(«linear», polynomial_derivative(q)))",
				By(
					shiftedDerivative,
					qFactor,
					linearDerivative,
					coefficientsBoth,
					qCoefficients,
					polynomial.DerivativeMul.Read(ring).AsFact().At(linear, q),
					polynomial.PolynomialOneMul.Read(ring).AsFact().At(q)))
			product := a.TermAs[Fun[Nat, A]]("polynomial_mul(«linear», polynomial_derivative(q))")
			productOver := a.Have(
				"that product is a polynomial over the chart",
				"polynomial_over(«chart», polynomial_mul(«linear», polynomial_derivative(q)))",
				By(
					linearOver,
					qDerivativeOver,
					polynomial.PolynomialMulOver.Read(ring).AsFact().At(linear, qDerivative)))
			derivativeAtY := a.Have(
				"so G′(y) is q(y) plus (y − ψ(y)) times q′(y)",
				"polynomial_eval(polynomial_derivative(G), y) = "+
					"polynomial_eval(q, y) + (y - ψ(y)) * polynomial_eval(polynomial_derivative(q), y)",
				By(
					productRule,
					qOver,
					productOver,
					linearOver,
					qDerivativeOver,
					yIn,
					linearValue.At(y),
					polynomial_evaluation.EvalAdd.Read(ring).AsFact().At(q, product, y),
					polynomial_evaluation.EvalMul.Read(ring).AsFact().At(linear, qDerivative, y)))
			difference := a.TermAs[A]("y - ψ(y)")
			qY := a.TermAs[A]("polynomial_eval(q, y)")
			qDerivativeY := a.TermAs[A]("polynomial_eval(polynomial_derivative(q), y)")
			GDerivativeY := a.TermAs[A]("polynomial_eval(polynomial_derivative(G), y)")
			differenceIn := a.Have(
				"y less its value lies in the chart",
				"y - ψ(y) ∈ «chart»",
				By(yIn, valuesIn, ring, comm_ring.SubIn.Read(ring)))
			vanishes := a.Have(
				"ψ kills y less its value",
				"ψ(y - ψ(y)) = M.zero",
				By(M, chartSubring, lInChart, hom, fixes, yIn, PointKillsDifference.At(m, l, chart, ψ, y)))
			products := a.Have(
				"the products of y − ψ(y) with q(y) and with q′(y) lie in the chart",
				"(y - ψ(y)) * polynomial_eval(q, y) ∈ «chart» ∧ "+
					"(y - ψ(y)) * polynomial_eval(polynomial_derivative(q), y) ∈ «chart»",
				By(
					differenceIn,
					evaluations,
					chartSubring,
					comm_ring.SubringMul.At(fieldRing, chart, difference, qY),
					comm_ring.SubringMul.At(fieldRing, chart, difference, qDerivativeY)))
			GDerivativeIn := a.Have(
				"G′(y) lies in the chart",
				"polynomial_eval(polynomial_derivative(G), y) ∈ «chart»",
				By(
					GOverChart,
					yIn,
					polynomial.DerivativeOverCarrier.Read(ring).AsFact().At(G),
					polynomial_evaluation.EvalIn.Read(ring)))
			images := a.Have(
				"ψ takes these values into l, so into the field",
				"ψ(polynomial_eval(q, y)) ∈ M.carrier ∧ "+
					"ψ(polynomial_eval(polynomial_derivative(q), y)) ∈ M.carrier ∧ "+
					"ψ(polynomial_eval(polynomial_derivative(G), y)) ∈ M.carrier ∧ "+
					"ψ(polynomial_eval(G, ψ(y))) ∈ M.carrier",
				BySets(
					ring_homomorphism.MapIn.Read(hom).AsFact().At(qY),
					ring_homomorphism.MapIn.Read(hom).AsFact().At(qDerivativeY),
					ring_homomorphism.MapIn.Read(hom).AsFact().At(GDerivativeY),
					ring_homomorphism.MapIn.Read(hom).AsFact().At(value),
					evaluations,
					GDerivativeIn,
					valueIn,
					lSubfield,
					field.SubfieldSubset.At(m, l)))
			mapped := a.Have(
				"ψ of G′(y) is ψ(q(y)) plus ψ(y − ψ(y)) times ψ(q′(y))",
				"ψ(polynomial_eval(polynomial_derivative(G), y)) = "+
					"ψ(polynomial_eval(q, y)) + ψ(y - ψ(y)) * ψ(polynomial_eval(polynomial_derivative(q), y))",
				By(
					derivativeAtY,
					evaluations,
					differenceIn,
					products,
					ring_homomorphism.MapAdd.Read(hom).AsFact().At(
						qY, a.TermAs[A]("(y - ψ(y)) * polynomial_eval(polynomial_derivative(q), y)")),
					ring_homomorphism.MapMul.Read(hom).AsFact().At(difference, qDerivativeY)))
			sameValue := a.Have(
				"so ψ(q(y)) = ψ(G′(y)), the second term vanishing",
				"ψ(polynomial_eval(q, y)) = ψ(polynomial_eval(polynomial_derivative(G), y))",
				ByArith(M, mapped, vanishes, images))
			congruence := a.Have(
				"ψ of minus the value of G at ψ(y) is ψ(y − ψ(y)) times ψ(q(y))",
				"ψ(-polynomial_eval(G, ψ(y))) = ψ(y - ψ(y)) * ψ(polynomial_eval(q, y))",
				By(
					relation,
					differenceIn,
					evaluations,
					ring_homomorphism.MapMul.Read(hom).AsFact().At(difference, qY)))
			zeroTimes := a.Have(
				"zero times ψ(q(y)) is zero",
				"M.zero * ψ(polynomial_eval(q, y)) = M.zero",
				ByArith(M, images))
			negatedKilled := a.Have(
				"so ψ kills minus the value of G at ψ(y), and its negative is ψ of the negative",
				"-ψ(polynomial_eval(G, ψ(y))) = M.zero",
				By(congruence, vanishes, zeroTimes, valueIn, ring_homomorphism.MapNeg.Read(hom).AsFact().At(value)))
			killed := a.Have(
				"so ψ kills the value of G at ψ(y)",
				"ψ(polynomial_eval(G, ψ(y))) = M.zero",
				ByArith(M, negatedKilled, images))
			h, multiple := a.UnpackAs[A](GroupPremises(valueInLine, pointIdeal[1].At(value)), "h")
			hData := a.Conjuncts(
				multiple,
				"h lies in the chart",
				"the value of G at ψ(y) less its image is (s − ψ(s)) h")
			hIn, hEquation := hData[0], hData[1]
			members := a.Have(
				"s, ψ(s), h and q(y) lie in the field",
				"s ∈ M.carrier ∧ ψ(s) ∈ M.carrier ∧ h ∈ M.carrier ∧ polynomial_eval(q, y) ∈ M.carrier",
				BySets(sInField, valuesIn, hIn, evaluations, chartInField))
			negated := a.Have(
				"minus h lies in the chart",
				"-h ∈ «chart»",
				By(hIn, chartSubring, comm_ring.SubringNeg.At(fieldRing, chart, h)))
			related := a.Have(
				"so (y − ψ(y)) q(y) is (s − ψ(s)) times −h",
				"(y - ψ(y)) * polynomial_eval(q, y) = (s - ψ(s)) * -h",
				ByArith(M, relation, hEquation, killed, members, valueIn, valuesIn, yInField))
			a.Take(qY)
			a.Take(a.TermAs[A]("-h"))
			a.Show(
				"q(y) and −h relate the two generators",
				By(evaluations, negated, sameValue, related))
		}),
})}

// MonogenicRelationInvertible — the kernel of a ring map ψ from l[s][y], monogenic
// over l[s], onto l fixing l is an invertible fractional ideal when s lies off l and
// the two generators s − ψ(s) and y − ψ(y) are related by
// (y − ψ(y))·g = (s − ψ(s))·h with ψ(g) ≠ 0: the kernel is generated by the two
// (MonogenicPointIdeal) and has residues in l, so the Jacobian criterion applies.
var MonogenicRelationInvertible = monogenicRelationInvertibleThm{family.Add(registry.ProofEntry{
	Name: "MonogenicRelationInvertible",
	Key:  "prop_73eca5c1e88c217e",
	Build: family.Theorem(Statement{
		Abbrev: Abbrev{
			{Name: "line", Text: "polynomial_image(field_ring(M), l, s)"},
			{Name: "chart", Text: "polynomial_image(field_ring(M), «line», y)"},
			{Name: "chartRing", Text: "restrict_ring(field_ring(M), «chart»)"},
		},
		Binders: "∀M:field_on(A). ∀l:set(A). ∀s y g h:A. ∀ψ:(A → A).",
		Hypotheses: []string{
			"subfield(M, l)",
			"s ∈ M.carrier",
			"y ∈ M.carrier",
			"s ∉ l",
			"ring_homomorphism(«chartRing», restrict_ring(field_ring(M), l), ψ)",
			"∀c:A. c ∈ l ⇒ ψ(c) = c",
			"g ∈ «chart»",
			"h ∈ «chart»",
			"ψ(g) ≠ M.zero",
			"(y - ψ(y)) * g = (s - ψ(s)) * h",
		},
		Conclusion: "invertible_fractional(field_ring(M), «chart», {x:A | x ∈ «chart» ∧ ψ(x) = M.zero})",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			l *Expr[Set[A]],
			s, y, g, h *Expr[A],
			ψ *Arrow[A, A],
			lSubfield, sInField, yInField, sOff, hom, fixes, gIn, hIn, gOff, related Fact,
		) {
			m := a.TermAs[FieldOps[A]]("M")
			fieldRing := a.TermAs[RingOps[A]]("field_ring(M)")
			chart := a.TermAs[Set[A]]("«chart»")
			kernel := a.TermAs[Set[A]]("{x:A | x ∈ «chart» ∧ ψ(x) = M.zero}")
			sm := a.MemberOf[on.M](s, sInField)
			ym := a.MemberOf[on.M](y, yInField)
			parts := a.Conjuncts(
				GroupPremises(M, lSubfield, sInField, yInField, hom, MonogenicChartSubring.At(m, l, s, y, ψ)),
				"l[s] is a subring of the field",
				"l[s] holds l",
				"the chart is a subring of the field",
				"the chart is a ring under the operations of M",
				"the chart holds l[s]",
				"the chart lies in the field",
				"the chart holds l",
				"the chart holds s",
				"the chart holds y",
				"ψ(s) lies in l",
				"ψ(y) lies in l")
			chartSubring, ring, chartInField := parts[2], parts[3], parts[5]
			lInChart, sIn, yIn, sValue := parts[6], parts[7], parts[8], parts[9]
			valuesIn := a.Have(
				"the values lie in the chart and in the field",
				"ψ(s) ∈ «chart» ∧ ψ(y) ∈ «chart» ∧ ψ(s) ∈ M.carrier ∧ ψ(y) ∈ M.carrier",
				BySets(sValue, parts[10], lInChart, chartInField))
			generators := a.Have(
				"s and y less their values lie in the chart",
				"s - ψ(s) ∈ «chart» ∧ y - ψ(y) ∈ «chart»",
				By(sIn, yIn, valuesIn, ring, comm_ring.SubIn.Read(ring)))
			generated := a.Conjuncts(
				GroupPremises(lSubfield, hom, fixes, MonogenicPointIdeal.Read(M).At(l, sm, ym, ψ)),
				"the kernel of ψ is generated by s − ψ(s) and y − ψ(y)",
				"an element of l[s] less its value is a multiple of s − ψ(s)")
			subfieldRing := a.Have(
				"l is a subfield of the ring of M",
				"ring_subfield(field_ring(M), M.inv, l)",
				By(
					lSubfield,
					field.SubfieldRingSubfield.Read(M).At(l, chart),
					field.RingSubfieldRestrict.At(fieldRing, chart, a.TermAs[Fun[A, A]]("M.inv"), l)))
			rational := a.Conjuncts(
				a.Unfolded(
					a.Have(
						"the kernel of ψ is a rational ideal of the chart",
						"rational_ideal(field_ring(M), l, «chart», {x:A | x ∈ «chart» ∧ ψ(x) = M.zero})",
						By(
							subfieldRing,
							hom,
							lInChart,
							fixes,
							ring_homomorphism.RingKernelDef.At(a.TermAs[A]("M.zero"), chart, ψ),
							quotient_ring.KernelFieldResidues.At(fieldRing, l, a.TermAs[Fun[A, A]]("M.inv"), chart, ψ))),
					quotient_ring.RationalIdealDef),
				"it is an ideal of the chart",
				"it does not hold one",
				"every element of the chart is a member of l modulo it")
			distinct := a.Have(
				"s differs from its value, which lies in l",
				"s - ψ(s) ≠ M.zero",
				Derive(func(b *Argument) {
					same := b.SupposeNot()
					equal := b.Have(
						"s would be its value",
						"s = ψ(s)",
						ByArith(M, same, sInField, valuesIn))
					b.Show(
						"and so lie in l",
						By(Normalized, equal, sValue, sOff))
				}))
			offKernel := a.Have(
				"g lies off the kernel",
				"g ∉ {x:A | x ∈ «chart» ∧ ψ(x) = M.zero}",
				By(gOff))
			a.Show(
				"the Jacobian criterion",
				By(
					chartSubring,
					lSubfield,
					lInChart,
					rational[2],
					generators,
					gIn,
					hIn,
					generated[0],
					related,
					distinct,
					offKernel,
					invertible_fractional_ideal.JacobianRelationInvertible.Read(M).At(
						l, chart, kernel, a.TermAs[A]("s - ψ(s)"), a.TermAs[A]("y - ψ(y)"), g, h)))
		}),
})}
